import java.io.*;
import java.util.*;

class Solution {
    public int maximumScore(int[] nums, int[] multipliers) {
        int m = multipliers.length;
        long[] dp = new long[m + 1];

        for (int i = m - 1; i >= 0; i--) {
            long mult = multipliers[i];
            for (int left = 0; left <= i; left++) {
                int right = i - left;
                int rightIndex = nums.length - 1 - right;
                long takeLeft = mult * nums[left] + dp[left + 1];
                long takeRight = mult * nums[rightIndex] + dp[left];
                dp[left] = Math.max(takeLeft, takeRight);
            }
        }

        return (int) dp[0];
    }
}

