        vector<long long> dp(m + 1, 0);

        for (int i = m - 1; i >= 0; --i) {
            long long mult = multipliers[i];
            for (int left = 0; left <= i; ++left) {
                int right = i - left;
                int rightIndex = (int)nums.size() - 1 - right;
                long long takeLeft = mult * nums[left] + dp[left + 1];
                long long takeRight = mult * nums[rightIndex] + dp[left];
                dp[left] = max(takeLeft, takeRight);
            }
        }

        return (int)dp[0];
    }
};

static int matchingBracket(const string& s, int start) {
    int depth = 0;
    for (int i = start; i < (int)s.size(); ++i) {
        if (s[i] == '[') ++depth;
        else if (s[i] == ']') {
            --depth;
            if (depth == 0) return i;
        }
    }
    return -1;
}

