    static int findMatchingBracket(String s, int start) {
        int depth = 0;
        for (int i = start; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') depth++;
            else if (c == ']') {
                depth--;
                if (depth == 0) return i;
            }
        }
        return -1;
    }

    static int[] parseArray(String s) {
        ArrayList<Integer> values = new ArrayList<>();
        int cur = 0;
        boolean inNumber = false;
        boolean negative = false;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '-') {
                negative = true;
            } else if (Character.isDigit(c)) {
                cur = cur * 10 + (c - '0');
                inNumber = true;
            } else if (inNumber) {
                values.add(negative ? -cur : cur);
                cur = 0;
                inNumber = false;
                negative = false;
            }
        }

        if (inNumber) values.add(negative ? -cur : cur);

        int[] result = new int[values.size()];
        for (int i = 0; i < values.size(); i++) result[i] = values.get(i);
        return result;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();

        int outer = line.indexOf('[');
        int first = line.indexOf('[', outer + 1);
        int firstEnd = findMatchingBracket(line, first);
        int second = line.indexOf('[', firstEnd + 1);
        int secondEnd = findMatchingBracket(line, second);

